// The per-phase tool-loop effort the insights mod calibrated from its ledger, read from the file it
// writes (a mod never reads another's store; the insights mod depends on this one, not the reverse).

import type { Phase } from '../types'
import type { Effort } from './policy'

// source: zetetic-insights hooks/learn.ts CALIBRATION_PATH, the file it writes.
export const CALIBRATION_PATH = '~/.claude/zetetic-insights/calibration.json'

export type LoopCeilings = Partial<Record<Phase, Effort>>

const LEVELS: readonly string[] = ['low', 'medium', 'high']

// Version 1, a `phases` object of low/medium/high; anything else is refused with the reason.
export const parseCeilings = (text: string): LoopCeilings => {
  const raw = JSON.parse(text) as { version?: unknown; phases?: Record<string, unknown> }
  if (raw.version !== 1 || typeof raw.phases !== 'object' || raw.phases === null)
    throw new Error('calibration.json is not version 1 with a phases object')
  const bad = Object.entries(raw.phases).find(([, e]) => typeof e !== 'string' || !LEVELS.includes(e))
  if (bad !== undefined) throw new Error(`calibration.json: ${bad[0]} has effort ${String(bad[1])}, not low, medium or high`)
  return raw.phases as LoopCeilings
}

files.hooks/agents.ts:
// Pure side of an agent type's definition: where its file is and which model and effort its
// frontmatter pins. `agent.spawn` carries the Agent call's `model` only, never the definition's
// (measured 2026-10-14: memory-writer, defined haiku, spawned with `model` undefined and resolved
// to claude-haiku-5-5 below the hook), so the router reads the file itself.

// source: ~/.claude/plugins/installed_plugins.json, the engine's record of installed plugins;
// `plugins["<name>@<marketplace>"][0].installPath` is the folder a session runs.
export const INSTALLED_PLUGINS_PATH = '~/.claude/plugins/installed_plugins.json'

// source: measured 2026-10-14 with a probe mod (agent.spawn result, turn.step): Explore, Plan and
// general-purpose spawned with no `model` from an opus parent resolved to the parent's model.
export const INHERITING_BUILT_INS: readonly string[] = ['Explore', 'Plan', 'general-purpose']

export type Definition = { model?: string; effort?: string }

// The folders from `dir` up to the filesystem root, nearest first; `/` and `\\` both separate.
export const ancestors = (dir: string): string[] => {
  const out: string[] = []
  let current = dir.length > 1 ? dir.replace(/[\\/]+$/, '') : dir
  for (;;) {
    out.push(current)
    const cut = Math.max(current.lastIndexOf('/'), current.lastIndexOf('\\'))
    if (cut < 0) return out
    if (cut === 0) return current === '/' ? out : [...out, '/']
    current = current.slice(0, cut)
  }
}

type Install = { scope?: unknown; projectPath?: unknown; installPath?: unknown }

// source: Claude Code's settings precedence (local over project over user), applied to the scopes
// `installed_plugins.json` records (`scope`: user, project, local; `projectPath` for the last two,
// measured 2026-10-14 on ~/.claude/plugins/installed_plugins.json). The engine's own choice among
// several entries is not documented in the mods reference: this order is the assumption (issue #11).
const USER = 2
const SCOPE_RANK: Record<string, number> = { local: 0, project: 1, user: USER }
const norm = (p: string): string => p.replace(/\\/g, '/').replace(/\/+$/, '')

// The install path a session in `cwd` runs: among the entries whose scope covers the session (user
// entries always, project and local ones when their `projectPath` is `cwd` or a folder above it) the
// narrowest scope, then the first listed. An entry with no scope is the user's.
export const activeInstallPath = (installs: readonly Install[], cwd: string): string | undefined => {
  const here = new Set(ancestors(cwd).map(norm))
  const covering: { path: string; rank: number }[] = []
  for (const i of installs) {
    if (typeof i.installPath !== 'string' || i.installPath === '') continue
    const rank = typeof i.scope === 'string' ? (SCOPE_RANK[i.scope] ?? USER) : USER
    if (rank !== USER && !(typeof i.projectPath === 'string' && here.has(norm(i.projectPath)))) continue
    covering.push({ path: i.installPath, rank })
  }
  // Array.prototype.sort is stable: equal ranks keep their listed order.
  return covering.sort((x, y) => x.rank - y.rank)[0]?.path
}

// The files that may define a type, in the engine's precedence: a plugin's `agents/<name>.md`
// for `<plugin>:<name>` (`agents/<sub>/<name>.md` for `<plugin>:<sub>:<name>`) from the install
// that runs in `cwd`, else the project's `.claude/agents/` in each of `projectDirs` (the folders from
// the working directory up to the repository root, nearest first), then the user's (`claudeDir`, the
// engine's config directory: `~/.claude` or CLAUDE_CONFIG_DIR).
export const definitionPaths = (
  type: string,
  installedPluginsJson: string | undefined,
  claudeDir: string,
  cwd: string,
  projectDirs: readonly string[],
): string[] => {
  const colon = type.indexOf(':')
  if (colon < 0) return [...projectDirs.map((dir) => `${dir}/.claude/agents/${type}.md`), `${claudeDir}/agents/${type}.md`]
  const plugin = type.slice(0, colon)
  // `<plugin>:<sub>:<name>` is the plugin's agents/<sub>/<name>.md.
  const name = type.slice(colon + 1).split(':').join('/')
  if (installedPluginsJson === undefined) return []
  let parsed: { plugins?: Record<string, Install[]> }
  try {
    parsed = JSON.parse(installedPluginsJson) as typeof parsed
  } catch (error) {
    // A record that is not JSON is not "plugin not installed": the caller is told which it is.
    throw new Error(`installed_plugins.json is not valid JSON (${error instanceof Error ? error.message : String(error)})`.slice(0, 160))
  }
  return Object.entries(parsed.plugins ?? {})
    .filter(([key]) => key.startsWith(`${plugin}@`))
    .map(([, installs]) => activeInstallPath(installs, cwd))
    .filter((p): p is string => p !== undefined)
    .map((root) => `${root}/agents/${name}.md`)
}

// The `model:` and `effort:` lines of the leading `---` block; a file without one pins nothing.
export const parseDefinition = (md: string): Definition => {
  const block = /^---\r?\n([\s\S]*?)\r?\n---/.exec(md)
  if (block === null) return {}
  const field = (name: string): string | undefined => {
    const m = new RegExp(`^${name}:[ \\t]*["']?([^"'\\s#]+)`, 'm').exec(block[1] ?? '')
    return m?.[1]
  }
  const model = field('model')
  const effort = field('effort')
  return { ...(model === undefined ? {} : { model }), ...(effort === undefined ? {} : { effort }) }
}

// The model a definition pins; `inherit` and an absent line both leave it to the parent.
export const pinnedModel = (d: Definition): string | undefined =>
  d.model === undefined || d.model === 'inherit' ? undefined : d.model

files.hooks/offload.ts:
// Lossless offload: a stream tool's result past the threshold is written whole to a file in the
// session's own tool-results directory, and the model reads a preview, the path, the size and an
// instruction to Read or grep the file. The threshold and the preview bound what enters the
// context; they never bound what is kept. Pure: the plan says what to write and what to show, the
// register file does the writing.

// source: Claude Code 2.1.300 persists a tool result past `ise(name, maxResultSizeChars, ceiling)`
// itself: Bash 30000 (`bashOutputMaxChars` default), Grep 20000, Glob and WebSearch 50000 (their
// 100000 is capped by the 50000 ceiling), WebFetch 50000 (read in the binary's strings, 2026-10-15;
// docs: code.claude.com tools-reference). 30000 is the native Bash default, so a result the engine
// already keeps (Grep past 20000, Bash past 30000) is never wrapped twice and Glob, WebFetch and
// WebSearch gain the 30000..50000 band the engine leaves inline.
export const DEFAULT_THRESHOLD_CHARS = 30000
// source: the preview the engine leaves in context for a result it persisted (`oxe = 2000`).
export const DEFAULT_PREVIEW_CHARS = 2000

// source: the engine's file API rejects a write over 4 MiB (index.d.ts, `$.fs`); a UTF-16 code unit
// is at most 3 UTF-8 bytes and a surrogate pair 4, so 1 000 000 units are at most 4 000 000 bytes.
export const PART_CHARS = 1_000_000

// The engine's own pointers to what it already keeps (`<persisted-output>`) or could not keep
// (`<truncated-output>`): a result that starts with one is not wrapped again.
const NATIVE_MARKERS = ['<persisted-output>', '<truncated-output>']
const MARKER = 'zetetic-autopilot-offload'

export type OffloadOptions = { thresholdChars: number; previewChars: number }

export type OffloadFile = { path: string; text: string }
export type OffloadPlan = { files: OffloadFile[]; message: string; chars: number; lines: number }

const isCount = (v: unknown): v is number => typeof v === 'number' && Number.isInteger(v) && v > 0

// The options as the user set them, each checked: a value that is not a positive whole number is
// named, and the default stands in its place. Left unchecked, NaN would make every result "past"
// the threshold.
export const offloadOptions = (
  threshold: unknown,
  preview: unknown,
): { options: OffloadOptions; problems: string[] } => {
  const problems: string[] = []
  const pick = (name: string, value: unknown, fallback: number): number => {
    if (value === undefined) return fallback
    if (isCount(value)) return value
    problems.push(`${name}=${JSON.stringify(value)} is not a positive whole number; using ${fallback}`)
    return fallback
  }
  const thresholdChars = pick('offload_threshold_chars', threshold, DEFAULT_THRESHOLD_CHARS)
  const asked = pick('offload_preview_chars', preview, DEFAULT_PREVIEW_CHARS)
  // A preview as long as the result would only add the pointer's lines to it.
  const previewChars = Math.min(asked, thresholdChars)
  if (previewChars < asked) problems.push(`offload_preview_chars=${asked} is past the threshold; using ${previewChars}`)
  return { options: { thresholdChars, previewChars }, problems }
}

// The directory the engine keeps this session's tool results in: the transcript
// `<projects>/<project>/<session>.jsonl` names it `<projects>/<project>/<session>/tool-results`.
// Undefined when the path is not that of the session `sessionId` (a /clear or a resume moved on).
export const toolResultsDir = (transcriptPath: string | undefined, sessionId: string): string | undefined => {
  if (transcriptPath === undefined || !transcriptPath.endsWith('.jsonl')) return undefined
  const stem = transcriptPath.slice(0, -'.jsonl'.length)
  const sep = stem.includes('/') || !stem.includes('\\') ? '/' : '\\'
  const segments = stem.split(sep)
  // The last segment must BE the session id, and no segment may climb out of the directory.
  if (segments.includes('..') || segments[segments.length - 1] !== sessionId) return undefined
  return `${stem}${sep}tool-results`
}

// A tool_use id is `toolu_...` or `call_...`; anything else a file name could not carry is replaced.
const fileSafe = (id: string): string => id.replace(/[^A-Za-z0-9_-]/g, '_')

// Splits at PART_CHARS, never between the two halves of a surrogate pair; the parts joined are the text.
export const parts = (text: string): string[] => {
  const out: string[] = []
  let at = 0
  while (at < text.length) {
    let end = Math.min(at + PART_CHARS, text.length)
    const last = text.charCodeAt(end - 1)
    if (end < text.length && last >= 0xd800 && last <= 0xdbff) end -= 1
    out.push(text.slice(at, end))
    at = end
  }
  return out
}

// The start of the text to show: up to `limit` characters, cut at a line break when one falls in the
// second half (the engine's own rule for its preview), never inside a surrogate pair.
export const previewOf = (text: string, limit: number): string => {
  let end = Math.min(limit, text.length)
  const last = text.charCodeAt(end - 1)
  if (end < text.length && last >= 0xd800 && last <= 0xdbff) end -= 1
  const head = text.slice(0, end)
  if (end === text.length) return head
  const lineEnd = head.lastIndexOf('\n')
  return lineEnd > end / 2 ? head.slice(0, lineEnd) : head
}

const count = (n: number): string => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ' ')

// pre:  `dir` is the session's tool-results directory, `toolUseId` the block's id, `joined` says the
//       text is several text blocks joined by a newline.
// post: undefined when the text is within the threshold or is one of the engine's own pointers;
//       otherwise `files` hold the text exactly (their texts joined are `text`, byte for byte) and
//       `message` is the preview, the path or paths, the size in characters and lines, and the
//       instruction to read the file. Nothing in it is a cut of the text except the preview, which
//       is named as the start.
export const planOffload = (
  text: string,
  toolUseId: string,
  dir: string,
  options: OffloadOptions,
  joined = false,
): OffloadPlan | undefined => {
  if (text.length <= options.thresholdChars) return undefined
  if (NATIVE_MARKERS.some((m) => text.startsWith(m))) return undefined
  const sep = dir.includes('/') || !dir.includes('\\') ? '/' : '\\'
  const pieces = parts(text)
  const name = `autopilot-${fileSafe(toolUseId)}`
  const files = pieces.map((piece, i) => ({
    path: `${dir}${sep}${name}${pieces.length === 1 ? '' : `.${i + 1}`}.txt`,
    text: piece,
  }))
  const lines = text.split('\n').length
  const where =
    files.length === 1
      ? `Full output saved to: ${files[0]?.path}`
      : `Full output saved in ${files.length} files of at most ${count(PART_CHARS)} characters, to be read in order:\n${files.map((f) => f.path).join('\n')}`
  const preview = previewOf(text, options.previewChars)
  const message = [
    `<${MARKER}>`,
    `Output too large (${count(text.length)} characters, ${count(lines)} lines). ${where}`,
    ...(joined ? ['The file holds the result\'s text blocks joined by a newline.'] : []),
    `Preview (the first ${count(preview.length)} characters):`,
    preview,
    'Nothing was removed: Read or grep the file for the rest.',
    `</${MARKER}>`,
  ].join('\n')

  return { files, message, chars: text.length, lines }
}

files.hooks/offloadrow.ts:
// The offload as the engine sees it: the blocks of one stored tool-result row, the files written for
// the long ones, the blocks the model will read. The plan itself is offload.ts (pure); this is the
// part that writes and reports, with the policy state and the cockpit rows behind a `Sink`.
import type { EngineInterface } from 'claude-code'

import { type OffloadOptions, type OffloadPlan, planOffload, toolResultsDir } from './offload'
import { resultText } from './policy'

export type Block = { type: string; tool_use_id?: unknown; content?: unknown }

// What the offload tells the rest of the mod: a result that stays whole and why, and one offloaded.
export type Sink = {
  note: (subject: string, reason: string) => Promise<void>
  offloaded: (plan: OffloadPlan, applied: boolean) => Promise<void>
}

export type Context = { options: OffloadOptions; enforce: boolean; transcriptPath: string | undefined; sink: Sink }

// The first plan whose files do not exist yet: `id`, then `id-2`, `id-3`... Nothing is ever overwritten.
async function freshPlan(
  $: EngineInterface,
  text: string,
  id: string,
  dir: string,
  ctx: Context,
  joined: boolean,
): Promise<OffloadPlan | undefined> {
  for (let n = 1; ; n++) {
    const plan = planOffload(text, n === 1 ? id : `${id}-${n}`, dir, ctx.options, joined)
    if (plan === undefined) return undefined
    let taken = false
    for (const f of plan.files) taken = taken || (await $.fs.exists(f.path))
    if (!taken) return plan
  }
}

// Writes each file whole; the reason of the first failure (4 MiB cap, a refusal, a full disk), else undefined.
async function writeAll($: EngineInterface, plan: OffloadPlan): Promise<string | undefined> {
  try {
    for (const f of plan.files) await $.fs.write(f.path, f.text)
  } catch (error) {
    return String(error).slice(0, 160)
  }
  return undefined
}

// The block the model will read in place of `block`: the pointer, as the string or the text block
// the result came as.
const pointer = <B extends Block>(block: B, message: string): B =>
  typeof block.content === 'string' ? { ...block, content: message } : { ...block, content: [{ type: 'text', text: message }] }

// pre:  `block` is a tool_result whose text is past the threshold (planOffload decides about the
//       engine's own pointers); `dir` is the session's tool-results directory or undefined.
// post: every block gets its own file name (the tool_use id, else `<row uuid>-<block index>`) and an
//       existing file is never overwritten (the next free `-N` suffix is used); the block unchanged (and a note saying why) when the directory is unknown or the write was
//       refused; under observe the block unchanged and nothing written; else the file(s) hold the
//       text whole and the returned block is the pointer. Nothing is ever dropped.
async function offloadOne<B extends Block>(
  $: EngineInterface,
  tool: string,
  block: B,
  text: string,
  dir: string | undefined,
  ctx: Context,
  fallbackId: string,
): Promise<B> {
  const id = typeof block.tool_use_id === 'string' ? block.tool_use_id : fallbackId
  const joined = Array.isArray(block.content) && block.content.length > 1
  const first = planOffload(text, id, dir ?? '', ctx.options, joined)
  if (first === undefined) return block
  if (dir === undefined) {
    await ctx.sink.note('tool-results directory', 'the session directory is not known; the result stays whole')
    return block
  }
  // Under enforce the name is the first free one; under observe nothing is written, so the plan stands.
  let plan = first
  if (ctx.enforce) {
    try {
      plan = (await freshPlan($, text, id, dir, ctx, joined)) ?? first
    } catch (error) {
      await ctx.sink.note(`${tool} result`, `not written, stays whole: ${String(error).slice(0, 160)}`)
      return block
    }
    const failure = await writeAll($, plan)
    if (failure !== undefined) {
      await ctx.sink.note(`${tool} result`, `not written, stays whole: ${failure}`)
      return block
    }
  }
  await ctx.sink.offloaded(plan, ctx.enforce)

  return ctx.enforce ? pointer(block, plan.message) : block
}

// The row's blocks with the long results offloaded; undefined when none changed.
export async function offloadBlocks<B extends Block>(
  $: EngineInterface,
  rowId: string,
  tool: string,
  blocks: readonly B[],
  ctx: Context,
): Promise<B[] | undefined> {
  let dir: string | undefined
  let known = false
  let changed = false
  const out: B[] = []
  for (const [index, block] of blocks.entries()) {
    const text = block.type === 'tool_result' ? resultText(block.content) : undefined
    if (text === undefined || text.length <= ctx.options.thresholdChars) {
      out.push(block)
      continue
    }
    // Asked once, and only when a result is past the threshold: most results never need the directory.
    if (!known) {
      dir = toolResultsDir(ctx.transcriptPath, await $.session.id())
      known = true
    }
    const next = await offloadOne($, tool, block, text, dir, ctx, `${rowId}-${index}`)
    changed = changed || next !== block
    out.push(next)
  }

  return changed ? out : undefined
}

files.hooks/paths.ts:
// Where `~/` lands on the machine a mod runs on. Pure: the engine follows `$` only inside the module
// that spells it, so each mod's register file reads the three variables and hands their values here.
//
// This file exists once per mod that expands `~/` (a mod cannot import a file from another mod: the
// engine refuses it, "outside the plugin's folder"), and every copy is byte-identical;
// scripts/check-shared.sh fails when one differs.

export type PathVars = { home: string | undefined; userProfile: string | undefined; configDir: string | undefined }
export type Placed = { path: string } | { reason: string }

const isSet = (value: string | undefined): value is string => value !== undefined && value !== ''
const trimmed = (dir: string): string => dir.replace(/[\\/]+$/, '')

// source: HOME is the home on macOS and Linux, USERPROFILE on Windows (cmd and PowerShell set it,
// not HOME); Node's os.homedir() reads them in that order on each platform. Unset in a sandbox: no
// place, said as such, never `/`.
export const homeOf = (vars: PathVars): Placed =>
  isSet(vars.home) ? { path: trimmed(vars.home) } : isSet(vars.userProfile) ? { path: trimmed(vars.userProfile) } : { reason: 'neither HOME nor USERPROFILE is set' }

// source: CLAUDE_CONFIG_DIR relocates the engine's `~/.claude` (plugins/, reference/, settings.json);
// without it the config directory is `<home>/.claude`.
export const configDirOf = (vars: PathVars): Placed => {
  if (isSet(vars.configDir)) return { path: trimmed(vars.configDir) }
  const home = homeOf(vars)

  return 'path' in home ? { path: `${home.path}/.claude` } : home
}

const CONFIG_PREFIX = '~/.claude'

// A path as the mods spell it: `~/.claude/...` is under the config directory, any other `~/...` under
// the home, anything else is already a place.
export const placePath = (vars: PathVars, path: string): Placed => {
  if (!path.startsWith('~/')) return { path }
  const isConfig = path === CONFIG_PREFIX || path.startsWith(`${CONFIG_PREFIX}/`)
  const base = isConfig ? configDirOf(vars) : homeOf(vars)
  if ('reason' in base) return { reason: `${path} has no place: ${base.reason}` }

  return { path: `${base.path}/${path.slice(isConfig ? CONFIG_PREFIX.length + 1 : 2)}` }
}

files.hooks/phases.ts:
// Pure side of the phases: which phase a loop (main or a subagent) is in, read off what it does.
// The owner's list (2026-10-14): planning, analysis, design, verification, test, review, report;
// implementation is added for the steps that write code, which none of the seven names.

import type { AdvisorUse, LoopPhases, Phase, PhaseRun, PhasesState } from '../types'

export const PHASES: readonly Phase[] = [
  'planning',
  'analysis',
  'design',
  'implementation',
  'verification',
  'test',
  'review',
  'report',
]

// source: ~/.claude/plugins/.../zetetic-team-subagents/commands/zetetic/engineering-loop.md, its
// nine steps; the cycle ledger records these, the view shows the phases (reconcilable both ways).
export const ENGINEERING_LOOP: Record<string, Phase> = {
  check: 'planning',
  recall: 'analysis',
  refine: 'planning',
  investigate: 'analysis',
  implement: 'implementation',
  verify: 'verification',
  benchmark: 'test',
  review: 'review',
  remember: 'report',
}

// When one step does several things, the phase it is in is the furthest along this order.
const RANK: Record<Phase, number> = {
  analysis: 0,
  planning: 1,
  design: 2,
  implementation: 3,
  verification: 4,
  test: 5,
  review: 6,
  report: 7,
}

// An agent type's own phase, from its role (the zetetic agents' descriptions); a type not listed
// is placed by what it does, step by step.
const BY_TYPE: [RegExp, Phase][] = [
  [/(^|:)(Plan|orchestrator|dispatch)$/, 'planning'],
  [/(^|:)(Explore|git-historian|research-scientist|data-scientist|professor)$/, 'analysis'],
  [/(^|:)(architect|ux-designer)$/, 'design'],
  [/(^|:)(test-engineer|experiment-runner)$/, 'test'],
  [/(^|:)(code-reviewer|security-auditor|reviewer-academic|advisor)$/, 'review'],
  [/(^|:)(memory-writer)$/, 'report'],
  [/(^|:)(engineer|frontend-engineer|refactorer|simplifier|dba|devops-engineer|mlops|latex-engineer|paper-writer)$/, 'implementation'],
]

export const typePhase = (type: string): Phase | undefined => BY_TYPE.find(([re]) => re.test(type))?.[1]

const PLANNING_TOOLS = new Set(['EnterPlanMode', 'ExitPlanMode', 'TaskCreate', 'TaskUpdate', 'TodoWrite'])
const READING_TOOLS = new Set(['Read', 'Grep', 'Glob', 'WebFetch', 'WebSearch', 'LSP', 'ToolSearch'])
const WRITING_TOOLS = new Set(['Edit', 'Write', 'NotebookEdit'])
// source: Claude Code tool names; the file reads any model can do. Not READING_TOOLS, which also holds
// web and search tools, and not the analysis phase, which also holds delegations, recalls and skills.
export const FILE_READ_TOOLS = new Set(['Read', 'Grep', 'Glob'])

// The one definition of a mechanical step: it calls tools and every call is a file read.
export const isFileReadStep = (uses: readonly { name: string }[]): boolean => uses.length > 0 && uses.every((u) => FILE_READ_TOOLS.has(u.name))

// Each pattern names a command by its head, the first words of a segment (`a && b`, `a; b`, `a | b`),
// so a word inside an argument (`grep pytest`, `git commit -m "fix tsc"`) names nothing.
// An inline check (`python3 -c '...; assert ...'`) carries its own `;`: read on the whole line.
const ASSERT_RUN = /(^|&&\s*)python3? -c .*\bassert\b/
const TEST_RUN = /^(python3? -m (pytest|unittest)|pytest|(npm|pnpm|yarn|bun) (run )?test|claude plugin test|go test|cargo test|(npx (-y )?)?(jest|vitest)|(sh|bash) \S*(mutation_check|reproduce)\S*)/
const CHECK_RUN = /^((uvx )?ruff\S*|(npx (-y )?(-p typescript )?)?tsc|mypy|pyright|(npx (-y )?)?eslint|claude plugin validate|python3? \S*check_craftsmanship|(sh|bash) \S*check-shared|python3? -m mcp_server\.doctor)\b/
const REVIEW_RUN = /^gh pr (review|diff)\b|^gh pr comment\b.*ZETETIC-REVIEW/
const DELIVER_RUN = /^(git (commit|push|tag)|gh pr (create|merge)|gh issue create)\b/
const READ_RUN = /^(ls|cat|head|tail|sed -n|grep|rg|find|wc|git (log|show|status|blame|diff)|gh (pr|issue) (view|list)|which|pwd|echo)\b/
const NEUTRAL_RUN = /^(cd|export|set|source|true)\b/
const DESIGN_FILE = /(^|\/)(docs\/adr\/|wiki\/|design\/)|ADR-\d|\.(md|tex)$/
const TEST_FILE = /(^|\/)(tests?|tests_py|__tests__)\/|\.(test|spec)\.[a-z]+$|_test\.[a-z]+$/

const SKILLS: [RegExp, Phase][] = [
  [/brainstorm|writing-plans|plan$/, 'planning'],
  [/debugging|understand-codebase|recall|research/, 'analysis'],
  [/design|architecture|adr|wiki-author/, 'design'],
  [/test-driven|testing/, 'test'],
  [/verif|integrity|provenance/, 'verification'],
  [/review/, 'review'],
]

const CORTEX = /^mcp__plugin_hypermnesia-mcp_cortex__/
const ARCH = /^mcp__plugin_ai-architect-mcp-codebase_ai-architect__/
const PRD = /^mcp__plugin_ai-architect-mcp-spec_prd-gen__/

const field = (input: unknown, name: string): string => {
  const v = (input as Record<string, unknown> | null)?.[name]
  return typeof v === 'string' ? v : ''
}

const segmentPhase = (segment: string): Phase | undefined => {
  if (segment === '' || NEUTRAL_RUN.test(segment)) return undefined
  if (REVIEW_RUN.test(segment)) return 'review'
  if (TEST_RUN.test(segment)) return 'test'
  if (CHECK_RUN.test(segment)) return 'verification'
  if (DELIVER_RUN.test(segment)) return 'report'
  return READ_RUN.test(segment) ? 'analysis' : 'implementation'
}

// The first line only (a heredoc's body is data); the furthest phase of its segments.
const bashPhase = (command: string): Phase => {
  const line = command.split('\n')[0] ?? ''
  if (ASSERT_RUN.test(line)) return 'test'
  return line
    .split(/&&|\|\||;|\|/)
    .map((s) => segmentPhase(s.trim().replace(/^([A-Z_]+=\S+\s+)+/, '')))
    .filter((p): p is Phase => p !== undefined)
    .reduce<Phase>((best, p) => (RANK[p] > RANK[best] ? p : best), 'analysis')
}

const mcpPhase = (name: string): Phase | undefined => {
  if (CORTEX.test(name)) {
    if (/__(remember|checkpoint|record_session_end)$/.test(name)) return 'report'
    if (/__wiki_(write|adr)$/.test(name)) return 'design'
    return 'analysis'
  }
  if (PRD.test(name)) return /validate|verification/.test(name) ? 'verification' : 'design'
  if (ARCH.test(name)) return /verif|gates|semantic_diff|validate/.test(name) ? 'verification' : 'analysis'
  return undefined
}

// The phase one tool call puts its loop in; undefined when the call says nothing about it.
export const toolPhase = (name: string, input: unknown): Phase | undefined => {
  if (PLANNING_TOOLS.has(name)) return 'planning'
  if (READING_TOOLS.has(name)) return 'analysis'
  if (WRITING_TOOLS.has(name)) {
    const path = field(input, 'file_path') || field(input, 'notebook_path')
    if (TEST_FILE.test(path)) return 'test'
    return DESIGN_FILE.test(path) ? 'design' : 'implementation'
  }
  if (name === 'Bash') return bashPhase(field(input, 'command'))
  if (name === 'Agent') return typePhase(field(input, 'subagent_type'))
  if (name === 'Skill') return SKILLS.find(([re]) => re.test(field(input, 'skill')))?.[1]
  return mcpPhase(name)
}

// A step's phase: the furthest along of its calls; a step that calls nothing and answers is the
// report. Undefined when nothing in it names a phase (the loop stays where it was).
export const stepPhase = (uses: readonly { name: string; input: unknown }[], answer: string): Phase | undefined => {
  if (uses.length === 0) return answer.trim() === '' ? undefined : 'report'
  return uses
    .map((u) => toolPhase(u.name, u.input))
    .filter((p): p is Phase => p !== undefined)
    .reduce<Phase | undefined>((best, p) => (best === undefined || RANK[p] > RANK[best] ? p : best), undefined)
}

export const LOOPS_CAP = 12 // source: own choice, the running agents and the last few done fit one pane

export const emptyPhases = (): PhasesState => ({ turnId: null, loops: [], advisor: { session: 0, uses: [] } })

// A loop keeps its place in the list; a new one goes last, the oldest finished ones make room.
const withLoop = (s: PhasesState, loop: LoopPhases): PhasesState => {
  if (s.loops.some((l) => l.id === loop.id)) return { ...s, loops: s.loops.map((l) => (l.id === loop.id ? loop : l)) }
  const loops = [...s.loops, loop]
  let excess = loops.length - LOOPS_CAP
  return {
    ...s,
    loops: loops.filter((l) => {
      if (excess <= 0 || l.status !== 'done' || l.id === 'main') return true
      excess -= 1
      return false
    }),
  }
}

// Main's row, reset at each turn: its phases are the turn's.
export const startTurn = (s: PhasesState, turnId: string, model: string, at: number): PhasesState =>
  withLoop({ ...s, turnId }, {
    id: 'main',
    type: 'main',
    description: 'main loop',
    model,
    effort: null,
    phase: null,
    runs: [],
    status: 'running',
    advisorCalls: 0,
    wrote: false,
    updatedAt: at,
  })

// The runs an agent made before its type was known, as one run of the type's phase. `reads` is the
// sum when every run carries it; a run recorded before it was counted leaves the sum absent.
const merged = (runs: readonly PhaseRun[], phase: Phase, at: number): PhaseRun => ({
  phase,
  effort: runs[runs.length - 1]?.effort ?? null,
  steps: runs.reduce((n, r) => n + r.steps, 0),
  errors: runs.reduce((n, r) => n + r.errors, 0),
  since: runs[0]?.since ?? at,
  ...(runs.every((r) => r.reads !== undefined) ? { reads: runs.reduce((n, r) => n + (r.reads ?? 0), 0) } : {}),
})

// A started subagent's row. Its steps may come in before the spawn answers (the engine runs the
// loop meanwhile): a row they opened is completed here, its runs and status kept.
export const spawned = (
  s: PhasesState,
  a: { id: string; type: string; description: string; model: string; at: number },
): PhasesState => {
  const phase = typePhase(a.type) ?? null
  const before = s.loops.find((l) => l.id === a.id)
  if (before !== undefined)
    return withLoop(s, {
      ...before,
      type: a.type,
      description: a.description,
      phase: phase ?? before.phase,
      runs: phase === null ? before.runs : [merged(before.runs, phase, a.at)],
    })
  return withLoop(s, {
    id: a.id,
    type: a.type,
    description: a.description,
    model: a.model,
    effort: null,
    phase,
    runs: phase === null ? [] : [{ phase, effort: null, steps: 0, errors: 0, since: a.at, reads: 0 }],
    status: 'running',
    advisorCalls: 0,
    wrote: false,
    updatedAt: a.at,
  })
}

const opened = (st: Step): LoopPhases => ({
  id: st.loopId,
  type: st.loopId === 'main' ? 'main' : 'agent',
  description: st.loopId === 'main' ? 'main loop' : 'subagent',
  model: st.model,
  effort: st.effort,
  phase: null,
  runs: [],
  status: 'running',
  advisorCalls: 0,
  wrote: false,
  updatedAt: st.at,
})

export type Step = {
  loopId: string
  model: string
  effort: string | null
  phase: Phase | undefined
  fileRead: boolean // isFileReadStep of the step's tool calls
  advisorCalls: number
  at: number
}

// An agent whose type names a phase stays in it (a reviewer reading files is still reviewing);
// main and an unplaced type move with what each step does.
export const stepped = (s: PhasesState, st: Step): PhasesState => {
  const loop = s.loops.find((l) => l.id === st.loopId) ?? opened(st)
  const fixed = loop.type !== 'main' && typePhase(loop.type) !== undefined
  const phase = fixed ? loop.phase : (st.phase ?? loop.phase)
  const last = loop.runs[loop.runs.length - 1]
  const runs =
    phase === null
      ? loop.runs
      : last !== undefined && last.phase === phase && last.effort === st.effort
        ? [...loop.runs.slice(0, -1), { ...last, steps: last.steps + 1, ...(last.reads === undefined ? {} : { reads: last.reads + (st.fileRead ? 1 : 0) }) }]
        : [...loop.runs, { phase, effort: st.effort, steps: 1, errors: 0, since: st.at, reads: st.fileRead ? 1 : 0 }]
  const advisor = loop.type === 'main' && st.advisorCalls > 0 ? adviced(s.advisor, s.turnId, loop, st) : s.advisor
  return {
    ...withLoop(s, {
      ...loop,
      model: st.model,
      effort: st.effort,
      phase,
      runs,
      advisorCalls: loop.advisorCalls + st.advisorCalls,
      wrote: loop.wrote || st.phase === 'implementation' || st.phase === 'design' || st.phase === 'test',
      updatedAt: st.at,
    }),
    advisor,
  }
}

export const USES_CAP = 20 // source: own choice, the pane lists the last advisor calls only

// The advisor (a server tool of the main loop) is counted with when it was called: before the
// turn wrote anything, after, or in the step that answered.
const adviced = (a: PhasesState['advisor'], turnId: string | null, loop: LoopPhases, st: Step): PhasesState['advisor'] => {
  const when: AdvisorUse['when'] = st.phase === 'report' ? 'at-completion' : loop.wrote ? 'after-write' : 'before-write'
  const use: AdvisorUse = { at: st.at, turnId, phase: loop.phase, when, calls: st.advisorCalls }
  return { session: a.session + st.advisorCalls, uses: [...a.uses, use].slice(-USES_CAP) }
}

// A tool call of the loop failed or was refused: counted on the run it happened in, the evidence
// the insights mod learns each phase's effort from.
export const erred = (s: PhasesState, loopId: string): PhasesState => {
  const loop = s.loops.find((l) => l.id === loopId)
  const last = loop?.runs[loop.runs.length - 1]
  if (loop === undefined || last === undefined) return s
  return withLoop(s, { ...loop, runs: [...loop.runs.slice(0, -1), { ...last, errors: last.errors + 1 }] })
}

export const finished = (s: PhasesState, loopId: string, at: number): PhasesState => {
  const loop = s.loops.find((l) => l.id === loopId)
  return loop === undefined ? s : withLoop(s, { ...loop, status: 'done', updatedAt: at })
}

